INSERT INTO `reviews` VALUES (1,'1',NULL,'Nguyễn Thu Trang','https://images.unsplash.com/photo-1544005313-94ddf0286df2?q=80&w=200&auto=format&fit=crop',5,'Áo vải cotton 100% dày dặn nhưng mặc rất mát và thấm hút mồ hôi tốt. Chữ thêu HOTEL sắc nét, giặt máy không lo bong tróc. Size M vừa người chuẩn đẹp!',NULL,'M','Trắng',1,'2026-03-10 07:30:00'),(2,'1',NULL,'Trần Hoàng Nam','https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?q=80&w=200&auto=format&fit=crop',5,'Form unisex mặc thoải mái, đường may cẩn thận, không có chỉ thừa. Đóng gói hộp rất lịch sự. Sẽ ủng hộ shop tiếp!',NULL,'L','Đen',1,'2026-03-12 02:15:00'),(3,'1',NULL,'Lê Minh Tuấn','https://images.unsplash.com/photo-1500648767791-00dcc994a43e?q=80&w=200&auto=format&fit=crop',4,'Chất lượng ổn áp so với tầm giá. Giao hàng nhanh, shipper thân thiện. Form áo rộng rãi đúng kiểu trẻ trung.',NULL,'XL','Trắng',1,'2026-03-14 09:45:00'),(4,'2',NULL,'Phạm Đăng Khoa','https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?q=80&w=200&auto=format&fit=crop',5,'Hình in graphic sắc nét, phối màu cực chất. Chất thun co giãn 4 chiều mặc đi chơi rất hợp.',NULL,'L','Đen',1,'2026-03-08 04:20:00'),(5,'2',NULL,'Đỗ Quốc Bảo','https://images.unsplash.com/photo-1522075469751-3a6694fb2f61?q=80&w=200&auto=format&fit=crop',5,'Rất thích form áo streetwear này, mặc lên tôn dáng và năng động. Cho shop 5 sao!',NULL,'M','Đen',1,'2026-03-11 11:05:00'),(6,'3',NULL,'Nguyễn Hải Yến','https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=200&auto=format&fit=crop',5,'Màu xanh mint pastel bên ngoài xinh xỉu luôn mn ơi! Vải nỉ da cá ấm áp mà không bị bí, không hề xù lông.',NULL,'M','Mint',1,'2026-03-05 06:10:00'),(7,'3',NULL,'Vũ Đức Thắng','https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?q=80&w=200&auto=format&fit=crop',5,'Áo dày dặn, bo tay và cổ chuẩn form. Mặc mùa này cực kỳ thích hợp.',NULL,'L','Mint',1,'2026-03-09 13:30:00'),(8,'4',NULL,'Bùi Phương Thảo','https://images.unsplash.com/photo-1517841905240-472988babdf9?q=80&w=200&auto=format&fit=crop',5,'Đầm đẹp xuất sắc luôn ạ! Tôn eo và che khuyết điểm rất tốt. Vải voan mềm rũ bay bổng, mặc đi tiệc hoặc du lịch chụp ảnh siêu nổi bật.',NULL,'M','Đỏ',1,'2026-03-01 08:00:00'),(9,'4',NULL,'Hoàng Bích Ngọc','https://images.unsplash.com/photo-1524504388940-b1c1722653e1?q=80&w=200&auto=format&fit=crop',5,'Váy có lớp lót kín đáo, hoa văn vintage sang chảnh. Ai cũng khen đầm đẹp.',NULL,'S','Đỏ',1,'2026-03-07 03:45:00'),(10,'5',NULL,'Lê Văn Hưng','https://images.unsplash.com/photo-1494790108377-be9c29b29330?q=80&w=200&auto=format&fit=crop',5,'Áo basic không thể thiếu trong tủ đồ, cotton mịn mát, cổ áo may chắc chắn không bị bai dão.',NULL,'L','Trắng',1,'2026-03-15 01:30:00'),(11,'6',NULL,'Đặng Thanh Hằng','https://images.unsplash.com/photo-1494790108377-be9c29b29330?q=80&w=200&auto=format&fit=crop',5,'Denim dày dặn đúng chuẩn, chi tiết rách và huy hiệu rất cá tính. Mặc lên hack chân dài miên man!',NULL,'M','Xanh Denim',1,'2026-03-14 10:15:00'),(12,'7',NULL,'Nguyễn Minh Quang','https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?q=80&w=200&auto=format&fit=crop',5,'Form blazer Hàn Quốc đứng dáng, chất vải tuyết mưa cao cấp, tone màu be rất sang. Rất đáng đồng tiền bát gạo!',NULL,'L','Be',1,'2026-03-12 12:20:00'),(13,'8',NULL,'Phan Mỹ Linh','https://images.unsplash.com/photo-1534528741775-53994a69daeb?q=80&w=200&auto=format&fit=crop',5,'Quần cạp cao mặc vào chân dài thêm mấy phần luôn, vải không nhăn đi làm cả ngày vẫn đứng form.',NULL,'M','Đen',1,'2026-03-13 07:10:00'),(14,'1',NULL,'Test User','https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=80&w=200&auto=format&fit=crop',5,'Sản phẩm tuyệt vời!',NULL,'M','Trắng',1,'2026-09-18 02:37:51'),(15,'1',NULL,'Huy Hoàng','https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?q=80&w=200&auto=format&fit=crop',5,'Áo mặc vừa vặn tôn dáng, vải rất thoáng mát!',NULL,'M','Đen',1,'2026-09-18 02:47:08'),(16,'5',2,'nguyễn văn a',NULL,5,'Sản phẩm rất đẹp, chất vải mát, mặc lên cực kỳ tôn dáng!',4,'L','#E5D3B3',1,'2026-09-18 06:44:10'),(17,'12',1,'Nguyen Van A',NULL,5,'Form áo tuyệt vời chuẩn Hàn Quốc!',7,'S','#000000',1,'2026-09-18 06:44:10'),(18,'13',1,'Nguyen Van A',NULL,5,'Sản phẩm rất đẹp, chất vải mát, mặc lên cực kỳ tôn dáng!',7,'M','Be',1,'2026-09-18 06:44:10'),(19,'116',NULL,'Hoàng Minh Tuấn',NULL,5,'Giày êm chân dã man, mình mang chạy bộ mỗi sáng 5km không hề bị đau gót hay cấn mũi. Rất đáng tiền!',NULL,'40','Đen',1,'2026-09-27 07:18:21'),(20,'117',NULL,'Đỗ Phương Linh',NULL,5,'Giày sneaker nữ hack dáng đỉnh chóp luôn nha mọi người, đế độn 5cm nhưng nhẹ tênh đi không bị mỏi xíu nào!',NULL,'37','Trắng',1,'2026-09-21 07:18:21'),(21,'118',NULL,'Vũ Quốc Cường',NULL,5,'Đôi chelsea boot da lộn này mặc với quần jean bụi bặm bao ngầu. Đóng gói hộp cứng cáp và giao nhanh!',NULL,'41','Nâu Cổ Điển',1,'2026-09-27 07:18:21'),(22,'27',NULL,'Phan Thanh Tùng',NULL,5,'Chất vải polo dày dặn mà mặc rất mát, cổ dệt cứng cáp giặt máy không lo bị quăn mép. Sẽ ủng hộ shop tiếp.',NULL,'L','Xanh Navy',1,'2026-10-04 07:18:21'),(23,'28',NULL,'Lê Quỳnh Trang',NULL,5,'Áo khoác gió cản gió và đi mưa nhỏ thoải mái. Form rộng năng động dễ phối đồ.',NULL,'M','Đen',1,'2026-09-26 07:18:21'),(24,'61',NULL,'Bùi Thanh Trúc',NULL,5,'Váy hoa nhí xinh xỉu, chất vải voan lụa nhẹ bay bổng, đi chơi chụp hình ai cũng khen.',NULL,'S','Be',1,'2026-09-28 07:18:21'),(25,'79',NULL,'Cao Thị Mỹ Duyên',NULL,5,'Bộ vest nữ mặc lên người cực kỳ sang trọng và quyền lực. Đường may và ve áo chuẩn chỉnh.',NULL,'M','Đen',1,'2026-09-24 07:18:21'),(26,'98',NULL,'Hồ Quang Vinh',NULL,5,'Đồng hồ dây da thật đeo rất ôm tay, mặt kính trong vắt kim trôi mượt mà.',NULL,'Freesize','Đen Sang Trọng',1,'2026-10-06 07:18:21'),(27,'13',NULL,'Nguyễn Đức Thắng',NULL,5,'Sneaker trắng basic phối với đồ gì cũng đẹp, da mềm dễ lau chùi vệ sinh.',NULL,'42','Trắng',1,'2026-09-29 07:18:21'),(28,'21',NULL,'Trương Gia Huy',NULL,5,'Đôi loafer da bóng này mang đi làm hay dự tiệc đều thanh lịch. 10 điểm cho chất lượng shop!',NULL,'40','Đen',1,'2026-10-09 07:18:21'),(29,'22',NULL,'Đinh Thúy Hằng',NULL,5,'Giày cao gót mũi nhọn gót cực kỳ chắc chắn, đi làm cả ngày ở văn phòng không bị đau chân.',NULL,'36','Đen',1,'2026-09-29 07:18:21'),(30,'1',1,'Nguyen Van A',NULL,5,'Sản phẩm đẹp xuất sắc, chất vải sờ rất mịn tay, mặc vào mát mẻ tôn dáng lắm!',NULL,'S','Đen',1,'2026-10-11 02:18:41'),(31,'10',2,'nguyễn văn a',NULL,5,'Giao hàng cực kỳ nhanh chóng, đóng gói hộp carton cứng cáp sang trọng. Rất hài lòng!',NULL,'M','Trắng',1,'2026-10-01 02:18:41'),(32,'100',3,'0912345678',NULL,5,'Chuẩn size như shop tư vấn trong bảng kích cỡ, màu sắc y hệt như hình chụp.',NULL,'L','Xám',1,'2026-10-05 02:18:41'),(33,'101',5,'Trần Thị B',NULL,5,'Đường kim mũi chỉ may rất cẩn thận, không có chỉ thừa nào. Chắc chắn sẽ ủng hộ shop tiếp.',NULL,'XL','Xanh navy',1,'2026-10-05 02:18:41'),(34,'102',6,'Lê Văn C',NULL,5,'Chất liệu cotton dày dặn, giặt máy không bị xù lông hay co rút. Đáng tiền!',NULL,'S','Đen',1,'2026-10-03 02:18:41'),(35,'103',7,'Hoàng Minh Tuấn',NULL,4,'Áo mặc ôm vừa vặn, màu xám sang trọng dễ phối đồ đi làm lẫn đi chơi.',NULL,'M','Trắng',1,'2026-10-10 02:18:41'),(36,'104',8,'Đỗ Phương Linh',NULL,5,'Shop tư vấn nhiệt tình, đổi trả hỗ trợ rất nhanh nếu lỡ chọn nhầm size. 5 sao!',NULL,'L','Xám',1,'2026-09-29 02:18:41'),(37,'105',9,'Phạm Thu Hà',NULL,5,'Sản phẩm đẹp xuất sắc, chất vải sờ rất mịn tay, mặc vào mát mẻ tôn dáng lắm!',NULL,'XL','Xanh navy',1,'2026-09-27 02:18:41'),(38,'106',10,'Vũ Quốc Cường',NULL,5,'Giao hàng cực kỳ nhanh chóng, đóng gói hộp carton cứng cáp sang trọng. Rất hài lòng!',NULL,'S','Đen',1,'2026-09-26 02:18:41'),(39,'107',11,'Bùi Thanh Trúc',NULL,5,'Chuẩn size như shop tư vấn trong bảng kích cỡ, màu sắc y hệt như hình chụp.',NULL,'M','Trắng',1,'2026-10-13 02:18:41'),(40,'108',12,'Đặng Hải Đăng',NULL,5,'Đường kim mũi chỉ may rất cẩn thận, không có chỉ thừa nào. Chắc chắn sẽ ủng hộ shop tiếp.',NULL,'L','Xám',1,'2026-10-04 02:18:41'),(41,'109',13,'Lê Quỳnh Trang',NULL,5,